import{_ as e,c as o,o as l,b0 as t}from"./chunks/framework.CLL9SSSf.js";const r="/linux-driver-docs/assets/module001.CjRs5A2W.png",_=JSON.parse('{"title":"LV005-内核模块简介","description":null,"frontmatter":{"title":"LV005-内核模块简介","date":"2026-01-17T10:44:34.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/drv-base/kmod/126d2d1547322437620ab769","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-17T10:44:34.579Z","fulluuid":"7620ab769e8847ceb27bf152d8c0a5b6","useduuid":"7620ab769"}},"headers":[],"relativePath":"sdoc/drv-base/kmod/126d2d1547322437620ab769.md","filePath":"sdoc/05-设备驱动基础/06-内核模块/LV005-内核模块简介.md","lastUpdated":1769002717000}'),i={name:"sdoc/drv-base/kmod/126d2d1547322437620ab769.md"};function n(d,a,s,c,u,h){return l(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="lv005-内核模块简介" tabindex="-1">LV005-内核模块简介 <a class="header-anchor" href="#lv005-内核模块简介" aria-label="Permalink to &quot;LV005-内核模块简介&quot;">​</a></h1><h2 id="一、内核" tabindex="-1">一、内核 <a class="header-anchor" href="#一、内核" aria-label="Permalink to &quot;一、内核&quot;">​</a></h2><p>前面我们已经大概了解了 linux 系统的体系结构，这里我们来了解一下内核。</p><p>内核，是一个操作系统的核心。是基于硬件的第一层软件扩充，提供操作系统的最基本的功能， 是操作系统工作的基础，决定着整个操作系统的性能和稳定性。</p><p>内核按照体系结构分为两类：<strong>微内核（Micro Kernel）</strong> 和 <strong>宏内核（Monolithic Kernel）</strong>。 在微内核架构中，内核只提供操作系统核心功能，如实现进程管理、存储器管理、进程间通信、I/O 设备管理等， 而其它的应用层 IPC、文件系统功能、设备驱动模块 则不被包含到内核功能中，属于微内核之外的模块，所以针对这些模块的修改不会影响到微内核的核心功能。 微内核具有动态扩展性强的优点。Windows 操作系统、华为的鸿蒙操作系统就属于这类微内核架构。</p><p>而宏内核架构是将上述包括微内核以及微内核之外的应用层 IPC、文件系统功能、设备驱动模块都编译成一个整体。 其优点是执行效率非常高，但缺点也是十分明显的，一旦我们想要修改、增加内核某个功能时（如增加设备驱动程序）都需要重新编译一遍内核。 Linux 操作系统正是采用了宏内核结构。为了解决这一缺点，linux 中引入了内核模块这一机制。</p><img src="'+r+'" alt="微内核与宏内核的体系结构"><h2 id="二、内核模块机制引入" tabindex="-1">二、内核模块机制引入 <a class="header-anchor" href="#二、内核模块机制引入" aria-label="Permalink to &quot;二、内核模块机制引入&quot;">​</a></h2><h3 id="_1-为什么要引入内核模块" tabindex="-1">1. 为什么要引入内核模块 <a class="header-anchor" href="#_1-为什么要引入内核模块" aria-label="Permalink to &quot;1. 为什么要引入内核模块&quot;">​</a></h3><p>Linux 是一个跨平台的操作系统，支持众多的设备，在 Linux 内核源码中有超过 50%的代码都与设备驱动相关。 Linux 为宏内核架构，如果开启所有的功能，内核就会变得十分臃肿。</p><p>尽管 <code>Linux</code> 是 &quot; 单块内核“(<code>monolithic</code>)的操作系统——这是说整个系统内核都运行于一个单独的保护域中，但是 <code>linux</code> 内核是模块化组成的，它允许内核在运行时动态地向其中插入或从中删除代码。这些代码(包括相关的子线程、数据、函数入口和函数出口)被一并组合在一个单独的二进制镜像中，即所谓的可装载内核模块，或简称为模块。</p><p>类似于浏览器、eclipse 这些软件的插件开发，Linux 提供了一种可以向正在运行的内核中插入新的代码段、在代码段不需要继续运行时也可以从内核中移除的机制，这个可以被插入、移除的代码段被称为内核模块。可用于加载到 linux 内核的文件后缀为 <code>.ko</code>，<code>.ko</code> 文件是 kernel object 文件，也就是 kernel 下的模块加载文件。</p><p>内核模块就是实现了某个功能的一段内核代码，在内核运行过程，可以加载这部分代码到内核中， 从而动态地增加了内核的功能。基于这种特性，我们进行设备驱动开发时，以内核模块的形式编写设备驱动， 只需要编译相关的驱动代码即可，无需对整个内核进行编译。</p><h3 id="_2-有什么好处" tabindex="-1">2. 有什么好处？ <a class="header-anchor" href="#_2-有什么好处" aria-label="Permalink to &quot;2. 有什么好处？&quot;">​</a></h3><p>内核模块的引入不仅提高了系统的灵活性，对于开发人员来说更是提供了极大的方便。 在设备驱动的开发过程中，我们可以随意将正在测试的驱动程序添加到内核中或者从内核中移除， 每次修改内核模块的代码不需要重新启动内核。 在开发板上，我们也不需要将内核模块程序，或者说设备驱动程序的 ELF 文件存放在开发板中， 免去占用不必要的存储空间。当需要加载内核模块的时候，可以通过挂载 NFS 服务器， 将存放在其他设备中的内核模块，加载到开发板上。 在某些特定的场合，我们可以按照需要加载/卸载系统的内核模块，从而更好的为当前环境提供服务。</p><h2 id="三、内核模块" tabindex="-1">三、内核模块 <a class="header-anchor" href="#三、内核模块" aria-label="Permalink to &quot;三、内核模块&quot;">​</a></h2><h3 id="_1-内核模块的定义" tabindex="-1">1. 内核模块的定义 <a class="header-anchor" href="#_1-内核模块的定义" aria-label="Permalink to &quot;1. 内核模块的定义&quot;">​</a></h3><p>了解了内核模块引入以及带来的诸多好处，我们可以建立起对内核模块的初步认识， 下面让我们来看看内核模块的具体的定义：<strong>内核模块全称 Loadable Kernel Module(LKM), 是一种在内核运行时加载一组目标代码来实现某个特定功能的机制</strong>。</p><p>模块是具有独立功能的程序，它可以被单独编译，但不能独立运行， 在运行时它被链接到内核作为内核的一部分在内核空间运行，这与运行在用户空间的进程是不一样的。 模块由一组函数和数据结构组成，用来实现一种文件系统、一个驱动程序和其他内核上层功能。 因此内核模块具备如下特点：</p><ul><li>模块本身不被编译入内核映像，这控制了内核的大小。</li><li>模块一旦被加载，它就和内核中的其它部分完全一样。</li></ul><blockquote><p>内核模块的 <strong>本质</strong>：一段隶属于内核的“<strong>动态</strong>”代码，与其它内核代码是同一个运行实体，共用同一套运行资源，只是存在形式上是独立的。</p></blockquote><h3 id="_2-内核模块的特点" tabindex="-1">2. 内核模块的特点 <a class="header-anchor" href="#_2-内核模块的特点" aria-label="Permalink to &quot;2. 内核模块的特点&quot;">​</a></h3><p>内核模块的出现，解决了以下问题：</p><ul><li>单内核扩展性差的缺点。</li><li>减小内核镜像文件体积，一定程度上节省内存资源。</li><li>提高开发效率。</li></ul><p>但是内核模块也有相应的缺点，就是它不能彻底解决稳定性低的缺点：内核模块代码出错可能会导致整个系统崩溃。</p><h3 id="_3-和驱动什么关系" tabindex="-1">3. 和驱动什么关系 <a class="header-anchor" href="#_3-和驱动什么关系" aria-label="Permalink to &quot;3. 和驱动什么关系&quot;">​</a></h3><p>我自己的理解就是，内核模块就是我们的 ko 文件，是对于 linux 内核而言。驱动就是这个 ko 文件实现功能操作硬件的那部分程序，是针对具体的硬件而言。</p>',27)])])}const b=e(i,[["render",n]]);export{_ as __pageData,b as default};
